    {
        for (i = 0; i < BATTLE_ENTRY_MAX; i ++)
        {
            charaindex = BattleArray[battleindex].Side[j].Entry[i].charaindex;

            if (CHAR_CHECKINDEX(charaindex) == FALSE)
            {
                continue;
            }

            if (CHAR_getInt(charaindex, CHAR_WHICHTYPE) != CHAR_TYPEPLAYER)
            {
                continue;
            }

