        /* Every native escape expands one byte to at most two bytes. */
        size_t capacity = 2 * lengths[i] + 1;
        work[i] = malloc(capacity);
        if (!work[i] || !makeEscapeString(input[i], work[i], (int)capacity)) goto done;
    }
    int written = snprintf(out, outlen, "%s" SPACESTRING "%s" SPACESTRING "%s",
                           work[0], work[1], work[2]);
    if (written >= 0 && written < outlen) result = 0;
    else out[0] = '\0'; /* never publish a truncated character snapshot */
done:
    for (int i = 0; i < 3; ++i) free(work[i]);
    return result;
}

